import{_ as t,H as l,f as i,i as e}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"中文版审读致谢","description":"","frontmatter":{},"headers":[],"relativePath":"Rust程序设计（第2版）/中文版审读致谢.md","filePath":"Rust程序设计（第2版）/中文版审读致谢.md","lastUpdated":1795533925000}'),a={name:"Rust程序设计（第2版）/中文版审读致谢.md"};function s(_,p,r,o,u,n){return l(),i("div",null,[...p[0]||(p[0]=[e('<h1 id="中文版审读致谢" tabindex="-1">中文版审读致谢 <a class="header-anchor" href="#中文版审读致谢" aria-label="Permalink to &quot;中文版审读致谢&quot;">​</a></h1><p>作为 Rust 与系统编程领域的经典，本书翻译难度较大。在此，诚挚地感谢在第 2 版中文版出版过程中参与公开审读活动的 30 位开发者（含一线专家与爱好者）。</p><p>各位审读专家针对译文提出了大量宝贵的意见与建议，你们严谨的治学态度和对 Rust 语言的深刻理解让译者与编辑受益匪浅，也让本书的译文质量更上一层楼。在此以表格形式列出 30位审读专家的姓名（按姓氏字母排序），各章及章名与为之贡献的专家对应。</p><p>审读划分</p><ul><li><p>章名审读专家</p></li><li><p>第 1 章 系统程序员也能享受美好陈骜、姜子龙、尚卓燃（PsiACE）、唐刚（</p></li></ul><p>第 1~3 章</p><ul><li><p>第 2 章 Rust 导览Tang）第 3 章 基本数据类型</p></li><li><p>第 4 章 所有权与移动陈翔（@翔翔的学习频道）、刘燚、陶叶港</p></li></ul><p>第 4~6 章</p><ul><li><p>第 5 章 引用（@scruel）、杨思杰第 6 章 表达式</p></li><li><p>第 7 章 错误处理</p></li></ul><p>第 7~9 章</p><ul><li><p>第 8 章 crate 与模块寸志、胡屹、苏胤榕、张卫滨</p></li><li><p>第 9 章 结构体</p></li><li><p>第 10 章 枚举与模式</p></li></ul><p>本书虽已出版，但内容品质的提升不会终止。译者、编辑、审读专家虽已尽力，但疏漏可能在所难免，如果大家在阅读过程中发现任何问题，欢迎将其提交到图灵社区本书的勘误处（ituring.com.cn/book/2846）。勘误经编辑确认之后会更正在重印书中。</p>',12)])])}const m=t(a,[["render",s]]);export{d as __pageData,m as default};
